---RefreshUI
---@param attribute table {
---         name : string  属性名称
---         preAttrNum : number 上一属性
---         attrNum : number 当前属性
---         isConversion : boolean 是否转换成百分比
---         icon : string  属性图标 【可选】
---         unlockTip : string  解锁提示 【可选】
---}
---@param position number
function UICultivateUpLevelAttrNode:RefreshUI(attribute, position, isMainAttrHighlight)
    -- self.ImgBg.Status = position % 2 == 0 and 2 or 1

    local unlockTip = attribute.unlockTip
    local isUnlock = string.isEmpty(attribute.unlockTip)
    KTool.SetActive(self.TxtLock.gameObject, not isUnlock)
    KTool.SetActive(self.Open.gameObject, isUnlock)
    if not isUnlock then
        self.TxtLock.text = unlockTip
        return
    end

    local icon = attribute.icon
    KTool.SetActive(self.ImgAttribute.gameObject, icon ~= nil)
    if icon then
        self.ImgAttribute:LoadSprite(icon)
    end

    local status = isMainAttrHighlight and 2 or 1
    self.Name.textComp.text = attribute.name
    self.Name.Status = status
    self.LeftNumText.textComp.text  = attribute_format(attribute.isConversion, attribute.preAttrNum)
    self.LeftNumText.Status = status

    local attrNum = attribute.attrNum
    local isNew = checkBool(attribute.isNew)
    KTool.SetActive(self.ImgNew.gameObject, isNew)
    KTool.SetActive(self.Item.gameObject, attrNum ~= nil)
    if attrNum then
        self.RightNumText.text = attribute_format(attribute.isConversion, attrNum)
    end

end

